#include <QApplication>
#include <QPushButton>

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);
    QPushButton btn("Clique aqui");

    QObject::connect(&btn, &QPushButton::clicked, []() {
        qDebug("Botão pressionado!");
    });

    btn.show();
    return app.exec();
}

